import json,os,pathlib,shutil,socket,subprocess,tempfile,time,urllib.request,urllib.parse,urllib.error
import yaml

def free_port():
 with socket.socket() as endpoint:endpoint.bind(('127.0.0.1',0));return endpoint.getsockname()[1]

class Loki:
 def __init__(self,auth=False,structured=False,configurator=None,directory=None):
  self.binary=shutil.which('loki');self.process=None;self.auth=auth;self.structured=structured;self.configurator=configurator;self.directory=directory
  if not self.binary:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Loki3.5.5 executable missing')
  version=subprocess.run([self.binary,'-version'],capture_output=True,text=True,timeout=3)
  if version.returncode or '3.5.5' not in version.stdout+version.stderr:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Loki3.5.5 required')
 def __enter__(self):
  self.temp=tempfile.TemporaryDirectory(prefix='of-loki-') if self.directory is None else None;self.root=pathlib.Path(self.temp.name if self.temp else self.directory);self.root.mkdir(parents=True,exist_ok=True);http=free_port();grpc=free_port()
  while grpc==http:grpc=free_port()
  self.base='http://127.0.0.1:'+str(http);self.log=(self.root/'server.log').open('wb')
  config={'auth_enabled':self.auth,'server':{'http_listen_address':'127.0.0.1','http_listen_port':http,'grpc_listen_address':'127.0.0.1','grpc_listen_port':grpc,'log_level':'error'},
   'common':{'instance_addr':'127.0.0.1','path_prefix':str(self.root),'replication_factor':1,'storage':{'filesystem':{'chunks_directory':str(self.root/'chunks'),'rules_directory':str(self.root/'rules')}},'ring':{'kvstore':{'store':'inmemory'}}},
   'schema_config':{'configs':[{'from':'2020-10-24','store':'tsdb','object_store':'filesystem','schema':'v13','index':{'prefix':'index_','period':'24h'}}]},
   'ingester':{'lifecycler':{'min_ready_duration':'0s','final_sleep':'0s','heartbeat_period':'100ms'},'wal':{'enabled':False}},
   'limits_config':{'allow_structured_metadata':self.structured,'max_query_parallelism':2,'tsdb_max_query_parallelism':2,'split_queries_by_interval':'0s','query_timeout':'5s'},
   'querier':{'max_concurrent':2},'analytics':{'reporting_enabled':False},'pattern_ingester':{'enabled':False},'compactor':{'working_directory':str(self.root/'compactor')}}
  if self.configurator:self.configurator(config,self.root)
  self.config=config;path=self.root/'config.yaml';path.write_text(yaml.safe_dump(config,sort_keys=False),encoding='utf8')
  try:
   self.process=subprocess.Popen([self.binary,'-config.file='+str(path)],cwd=self.root,stdout=self.log,stderr=self.log,env={**os.environ,'GOMAXPROCS':'2','GOMEMLIMIT':'192MiB','HOME':str(self.root)})
   self.wait(lambda:self.request('/ready')==b'ready\n','private HTTP readiness',seconds=12)
   print('NATIVE_LOKI_READY:3.5.5',flush=True);return self
  except BaseException:self.__exit__(None,None,None);raise
 def request(self,path,data=None,tenant=None,headers=None):
  outgoing={'Content-Type':'application/json',**(headers or {})}
  if tenant is not None:outgoing['X-Scope-OrgID']=tenant
  request=urllib.request.Request(self.base+path,data=None if data is None else json.dumps(data,ensure_ascii=False).encode(),headers=outgoing)
  with urllib.request.build_opener(urllib.request.ProxyHandler({})).open(request,timeout=3) as response:
   raw=response.read();return json.loads(raw) if raw and 'json' in response.headers.get('Content-Type','') else raw
 def wait(self,predicate,description,seconds=5):
  deadline=time.monotonic()+seconds
  while time.monotonic()<deadline:
   if self.process.poll() is not None:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Loki exited: '+(self.root/'server.log').read_text(errors='replace')[-2500:])
   try:
    value=predicate()
    if value:return value
   except (OSError,urllib.error.URLError):pass
   time.sleep(.04)
  raise AssertionError('native Loki deadline: '+description)
 def push(self,streams,tenant=None):
  result=self.request('/loki/api/v1/push',{'streams':streams},tenant=tenant);assert result==b''
 def logs(self,query,start,end,tenant=None):
  params={'query':query,'start':str(start),'end':str(end),'direction':'forward','limit':'1000'}
  result=self.request('/loki/api/v1/query_range?'+urllib.parse.urlencode(params),tenant=tenant);assert result['status']=='success' and result['data']['resultType']=='streams';return result['data']['result']
 def metric(self,query,at,tenant=None):
  result=self.request('/loki/api/v1/query?'+urllib.parse.urlencode({'query':query,'time':str(at)}),tenant=tenant);assert result['status']=='success' and result['data']['resultType']=='vector';return result['data']['result']
 def __exit__(self,*args):
  if self.process is not None:
   if self.process.poll() is None:self.process.terminate()
   try:self.process.wait(timeout=4)
   except subprocess.TimeoutExpired:self.process.kill();self.process.wait(timeout=2)
  if getattr(self,'log',None):self.log.close()
  if self.temp:self.temp.cleanup()

